#!/bin/sh
# First start of the bundle's database: the application role (no
# BYPASSRLS: row-level security backs every tenant predicate; migrations only
# grant to it). Its password is generated by the gateway (hex, so it needs no
# quoting).
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname scheduler <<SQL
CREATE ROLE scheduler_app LOGIN PASSWORD '${SCHEDULER_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE scheduler TO scheduler_app;
SQL
